        {
            Ok(result) => {
                let parsed: serde_json::Value = serde_json::from_str(&result).unwrap_or_default();
                Ok(Response::new(VerifyMagicLinkResponse {
                    success: parsed
                        .get("success")
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    user_id: parsed
                        .get("user_id")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    email: parsed
                        .get("email")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
