                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    is_admin: user_data
                        .as_object()
                        .and_then(|o| o.get("is_admin"))
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    registered_at: None,
                    last_active: None,
                }));
            }
        }

        let args = simd_json::json!({
            "email": req.email,
            "user_id": req.user_id,
            "domain": req.domain
        });

        match self
            .registration_dbus_call("get_user_status", &args.to_string())
            .await
        {
            Ok(result) => {
                let parsed: serde_json::Value = serde_json::from_str(&result).unwrap_or_default();
                Ok(Response::new(GetUserStatusResponse {
                    registered: parsed
                        .get("registered")
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    user_id: parsed
                        .get("user_id")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    email: parsed
                        .get("email")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    email_verified: parsed
                        .get("email_verified")
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    wireguard_public_key: parsed
                        .get("wireguard_public_key")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    assigned_ip: parsed
