                    )
                    .await;

                Ok(Response::new(RegisterUserResponse {
                    success: false,
                    user_id,
                    message: "Registration D-Bus service unavailable; user recorded in state store"
                        .to_string(),
                    assigned_ip: String::new(),
                    wireguard_config: String::new(),
                    registered_at: Some(OperationGrpcServer::now_ts()),
                }))
            }
        }
    }

    async fn get_user_status(
        &self,
        request: Request<GetUserStatusRequest>,
    ) -> Result<Response<GetUserStatusResponse>, Status> {
        let req = request.into_inner();

        // Check state store first
        let state = self.mutation_engine.get_state("registration").await;
        if let Some(ref st) = state
            && let Some(users) = st.as_object().and_then(|o| o.get("users"))
        {
            // Search by email or user_id
            if let Some(user_data) = users.as_object().and_then(|o| {
                // Try user_id first
                if !req.user_id.is_empty() {
                    o.get(&req.user_id)
                } else {
                    // Search by email
                    o.iter().find_map(|(_, v)| {
                        if v.as_object()
                            .and_then(|u| u.get("email"))
                            .and_then(|e| e.as_str())
                            == Some(&req.email)
                        {
                            Some(v)
                        } else {
                            None
                        }
                    })
                }
            }) {
                return Ok(Response::new(GetUserStatusResponse {
                    registered: true,
                    user_id: user_data
                        .as_object()
                        .and_then(|o| o.get("user_id"))
                        .and_then(|v| v.as_str())
                        .unwrap_or(&req.user_id)
                        .to_string(),
                    email: user_data
                        .as_object()
                        .and_then(|o| o.get("email"))
                        .and_then(|v| v.as_str())
                        .unwrap_or(&req.email)
                        .to_string(),
                    email_verified: user_data
                        .as_object()
                        .and_then(|o| o.get("email_verified"))
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    wireguard_public_key: user_data
                        .as_object()
                        .and_then(|o| o.get("wireguard_public_key"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    assigned_ip: user_data
                        .as_object()
                        .and_then(|o| o.get("assigned_ip"))
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    is_admin: user_data
                        .as_object()
                        .and_then(|o| o.get("is_admin"))
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    registered_at: None,
                    last_active: None,
                }));
            }
        }

        let args = simd_json::json!({
            "email": req.email,
            "user_id": req.user_id,
            "domain": req.domain
        });

        match self
            .registration_dbus_call("get_user_status", &args.to_string())
            .await
        {
            Ok(result) => {
                let parsed: serde_json::Value = serde_json::from_str(&result).unwrap_or_default();
                Ok(Response::new(GetUserStatusResponse {
                    registered: parsed
                        .get("registered")
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    user_id: parsed
                        .get("user_id")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    email: parsed
                        .get("email")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    email_verified: parsed
                        .get("email_verified")
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    wireguard_public_key: parsed
                        .get("wireguard_public_key")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    assigned_ip: parsed
                        .get("assigned_ip")
                        .and_then(|v| v.as_str())
                        .unwrap_or("")
                        .to_string(),
                    is_admin: parsed
                        .get("is_admin")
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false),
                    registered_at: None,
                    last_active: None,
                }))
            }
            Err(_) => Ok(Response::new(GetUserStatusResponse {
                registered: false,
                user_id: String::new(),
                email: req.email,
                email_verified: false,
                wireguard_public_key: String::new(),
